<?php $pageTitle='Admin Dashboard'; require '../includes/functions.php'; require_admin(); require '_header.php';
$sales=$pdo->query('SELECT COALESCE(SUM(total_amount),0) FROM sales')->fetchColumn(); $orders=$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn(); $pending=$pdo->query("SELECT COUNT(*) FROM orders WHERE status='Pending'")->fetchColumn(); $customers=$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn(); $low=$pdo->query('SELECT COUNT(*) FROM products WHERE stock<=low_stock_level')->fetchColumn(); $best=$pdo->query('SELECT name,sold_count FROM products ORDER BY sold_count DESC LIMIT 5')->fetchAll(); $monthly=$pdo->query("SELECT DATE_FORMAT(sale_date,'%b') m, SUM(total_amount) t FROM sales GROUP BY MONTH(sale_date), DATE_FORMAT(sale_date,'%b') ORDER BY MIN(sale_date)")->fetchAll(); ?>
<div class="d-flex justify-content-between align-items-center mb-4"><h1 class="fw-bold">Dashboard Analytics</h1><span class="badge bg-danger">Notifications: <?= $pending ?> pending</span></div><div class="row g-3"><div class="col-md-3"><div class="dash-card p-3"><h6>Total Sales</h6><h3><?= money($sales) ?></h3></div></div><div class="col-md-3"><div class="dash-card p-3"><h6>Total Orders</h6><h3><?= $orders ?></h3></div></div><div class="col-md-3"><div class="dash-card p-3"><h6>Pending Orders</h6><h3><?= $pending ?></h3></div></div><div class="col-md-3"><div class="dash-card p-3"><h6>Total Customers</h6><h3><?= $customers ?></h3></div></div><div class="col-md-3"><div class="dash-card p-3"><h6>Low Stock Alerts</h6><h3><?= $low ?></h3></div></div></div><div class="row g-4 mt-2"><div class="col-lg-8"><div class="bg-white p-4 rounded-4 shadow-sm"><h4>Monthly Sales Graph</h4><canvas id="salesChart"></canvas></div></div><div class="col-lg-4"><div class="bg-white p-4 rounded-4 shadow-sm"><h4>Best Selling Products</h4><?php foreach($best as $b): ?><div class="d-flex justify-content-between border-bottom py-2"><span><?= e($b['name']) ?></span><b><?= $b['sold_count'] ?></b></div><?php endforeach; ?></div></div></div><script>window.addEventListener('load',function(){new Chart(document.getElementById('salesChart'),{type:'bar',data:{labels:<?= json_encode(array_column($monthly,'m')) ?>,datasets:[{label:'Sales',data:<?= json_encode(array_column($monthly,'t')) ?>,backgroundColor:'#D62828',borderColor:'#F4C400'}]}});});</script><?php require '_footer.php'; ?>